using System.ComponentModel;
using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;
using System.Runtime.InteropServices;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    // .NET 9 breaking change: StatusStrip now defaults to ToolStripSystemRenderer
    // instead of ToolStripProfessionalRenderer. Explicitly set the renderer to
    // preserve the .NET 8 visual appearance.
    private StatusStrip _statusStrip;

    public MyControl()
    {
        _statusStrip = new StatusStrip();
        _statusStrip.RenderMode = ToolStripRenderMode.Professional;
        Controls.Add(_statusStrip);
    }

    // .NET 9 breaking change: IWindowsFormsEditorService.DropDownControl no longer
    // accepts null. Guard against null before calling.
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is null)
        {
            throw new ArgumentNullException(nameof(control),
                "DropDownControl no longer accepts null in .NET 9.");
        }
        editorService.DropDownControl(control);
    }

    // .NET 9 breaking change: COM interop now uses GeneratedComInterface.
    // P/Invoke signatures should use LibraryImport (source-generated) instead of DllImport.
    [LibraryImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    internal static partial bool ShowWindow(IntPtr hWnd, int nCmdShow);
}

